"""PDF138 printed 267–268: 8.1 introduction to attributes; 8.1.1 notation (symbols, positive/negative classes, class frequency); 8.1.2 classification (dichotomy, two-way) with tree figures."""
from class12_statistics_common import Builder, save
from class12_statistics_figs import attr_tree

b = Builder()
b.h('8.1 Introduction to attributes', '8.1 صفات کا تعارف', '8.1 د صفتونو پېژندنه')
b.p('In our daily life, we study the characteristics like gender, health, satisfaction, religion, colour etc. that cannot be measured and expressed quantitatively but instead of its qualitative or descriptive nature, only their presence or absence can be noticed. These descriptive or qualitative characteristics are called attributes. Attributes cannot be measured accurately but they can be divided into classes and their numbers in each class can be counted e.g. the above characteristics can be classified as male or female, healthy or unhealthy, satisfied or unsatisfied, Muslim or non-Muslim, white or black etc.',
    'اپنی روزمرہ زندگی میں ہم جنس، صحت، اطمینان، مذہب، رنگ وغیرہ جیسی خصوصیات کا مطالعہ کرتے ہیں جنہیں مقداری طور پر ناپا اور ظاہر نہیں کیا جا سکتا بلکہ ان کی کیفیتی یا بیانیہ نوعیت کی وجہ سے صرف ان کی موجودگی یا غیر موجودگی دیکھی جا سکتی ہے۔ ان بیانیہ یا کیفیتی خصوصیات کو صفات کہتے ہیں۔ صفات کو درست طور پر ناپا نہیں جا سکتا لیکن انہیں جماعتوں میں تقسیم کیا جا سکتا ہے اور ہر جماعت میں ان کی تعداد گنی جا سکتی ہے، مثلاً مندرجہ بالا خصوصیات کو مرد یا عورت، صحت مند یا غیر صحت مند، مطمئن یا غیر مطمئن، مسلم یا غیر مسلم، سفید یا سیاہ وغیرہ میں درجہ بند کیا جا سکتا ہے۔',
    'په ورځني ژوند کې موږ د جنس، روغتیا، رضایت، دین، رنګ او نورو په څېر ځانګړنې څېړو چې په کمي ډول نه اندازه کېږي او نه ښودل کېږي، بلکې د خپل کیفي یا تشریحي ماهیت له امله یوازې د هغو شتون یا نشتوالی لیدل کېدای شي. دې تشریحي یا کیفي ځانګړنو ته صفتونه وایي. صفتونه په دقیق ډول نه اندازه کېږي خو په ټولګیو وېشل کېدای شي او په هر ټولګي کې د هغو شمېر شمېرل کېدای شي، د بېلګې په توګه پورتنۍ ځانګړنې د نارینه یا ښځینه، روغ یا ناروغ، راضي یا ناراضي، مسلمان یا نامسلمان، سپین یا تور او نورو په توګه ډلبندي کېدای شي.')
b.h('8.1.1 Notation and terminology for attributes', '8.1.1 صفات کے لیے علامات اور اصطلاحات', '8.1.1 د صفتونو لپاره نښې او اصطلاحګانې')
b.h('Symbols', 'علامات', 'نښې')
b.p('For the sake of convenience capital English letters A, B, C… are used to denote presence of attributes and the Greek letters α, β, γ… denote the absence of these attributes respectively. For example if A represents the class “Muslim”, then α will represent the class “non-Muslim”. Similarly, if we are studying two or more attributes, their combination can be represented by combining the letters representing the attributes. For example, if A represent “blindness” and B “deafness”, then AB will represent the “blindness and deafness”. Similarly, if A represents the “Muslim” and B “male”, then the following four classes will be formed for the presence or absence of these attributes',
    'سہولت کے لیے انگریزی کے بڑے حروف A، B، C… صفات کی موجودگی اور یونانی حروف α، β، γ… بالترتیب ان صفات کی غیر موجودگی ظاہر کرنے کے لیے استعمال ہوتے ہیں۔ مثلاً اگر A جماعت “مسلم” کو ظاہر کرے تو α جماعت “غیر مسلم” کو ظاہر کرے گا۔ اسی طرح اگر ہم دو یا زیادہ صفات کا مطالعہ کر رہے ہوں تو ان کے امتزاج کو صفات ظاہر کرنے والے حروف ملا کر ظاہر کیا جا سکتا ہے۔ مثلاً اگر A “نابینا پن” اور B “بہرا پن” کو ظاہر کرے تو AB “نابینا پن اور بہرا پن” کو ظاہر کرے گا۔ اسی طرح اگر A “مسلم” اور B “مرد” کو ظاہر کرے تو ان صفات کی موجودگی یا غیر موجودگی کے لیے درج ذیل چار جماعتیں بنیں گی',
    'د اسانتیا لپاره د انګلیسي لوی توري A، B، C… د صفتونو د شتون او یوناني توري α، β، γ… په ترتیب سره د دې صفتونو د نشتوالي د ښودلو لپاره کارول کېږي. د بېلګې په توګه که A د “مسلمان” ټولګی ښيي، نو α به د “نامسلمان” ټولګی ښيي. همداسې که موږ دوه یا ډېر صفتونه څېړو، د هغو ترکیب د صفتونو ښوونکو تورو په یوځای کولو ښودل کېدای شي. د بېلګې په توګه که A “ړوندوالی” او B “کوڼوالی” ښيي، نو AB به “ړوندوالی او کوڼوالی” ښيي. همداسې که A “مسلمان” او B “نارینه” ښيي، نو د دې صفتونو د شتون یا نشتوالي لپاره به لاندې څلور ټولګي جوړ شي')
b.group('lines', [
    ('i) Muslim and male = AB', 'i) مسلم اور مرد = AB', 'i) مسلمان او نارینه = AB'),
    ('ii) Muslim and female = Aβ', 'ii) مسلم اور عورت = Aβ', 'ii) مسلمان او ښځینه = Aβ'),
    ('iii) Non-Muslim and male = αB', 'iii) غیر مسلم اور مرد = αB', 'iii) نامسلمان او نارینه = αB'),
    ('iv) Non-Muslim an female = αβ', 'iv) غیر مسلم اور عورت = αβ', 'iv) نامسلمان او ښځینه = αβ'),
])
b.h('Positive and negative classes', 'مثبت اور منفی جماعتیں', 'مثبت او منفي ټولګي')
b.p('The classes A, B, AB are called positive classes because they contain the presence of attributes. The classes α, β, αβ are called negative classes because they contain absence of the attributes. The classes Aβ, αB contain both presence and absence of the attributes, hence are called mixed classes.',
    'جماعتیں A، B، AB مثبت جماعتیں کہلاتی ہیں کیونکہ ان میں صفات کی موجودگی ہوتی ہے۔ جماعتیں α، β، αβ منفی جماعتیں کہلاتی ہیں کیونکہ ان میں صفات کی غیر موجودگی ہوتی ہے۔ جماعتیں Aβ، αB میں صفات کی موجودگی اور غیر موجودگی دونوں ہوتی ہیں، لہٰذا انہیں مخلوط جماعتیں کہتے ہیں۔',
    'ټولګي A، B، AB مثبت ټولګي بلل کېږي ځکه چې د صفتونو شتون لري. ټولګي α، β، αβ منفي ټولګي بلل کېږي ځکه چې د صفتونو نشتوالی لري. ټولګي Aβ، αB د صفتونو شتون او نشتوالی دواړه لري، نو ګډ ټولګي بلل کېږي.')
b.h('Class frequency', 'جماعت کا تعدد', 'د ټولګي تکرار')
b.p('The number of observations falling in a class is called frequency of the class. For attributes class frequencies are denoted by enclosing the class symbols in parentheses.', 'کسی جماعت میں آنے والے مشاہدات کی تعداد جماعت کا تعدد کہلاتی ہے۔ صفات کے لیے جماعتی تعدد کو جماعت کی علامات قوسین میں بند کر کے ظاہر کیا جاتا ہے۔', 'په یوه ټولګي کې د راتلونکو مشاهدو شمېر د ټولګي تکرار بلل کېږي. د صفتونو لپاره د ټولګي تکرارونه د ټولګي نښې په قوسونو کې ایښودو سره ښودل کېږي.')
b.p('Thus (A) denotes frequency of class/attribute A. (B) denotes frequency of attributes B. Similarly, (AB) denotes the number of individuals / objects possessing both attributes A and B. (ABC) is frequency for class ABC and so on.', 'یوں (A) جماعت/صفت A کا تعدد ظاہر کرتا ہے۔ (B) صفت B کا تعدد ظاہر کرتا ہے۔ اسی طرح (AB) ان افراد / اشیاء کی تعداد ظاہر کرتا ہے جن میں دونوں صفات A اور B ہوں۔ (ABC) جماعت ABC کا تعدد ہے، وغیرہ۔', 'نو (A) د A ټولګي/صفت تکرار ښيي. (B) د B صفت تکرار ښيي. همداسې (AB) د هغو کسانو / شیانو شمېر ښيي چې دواړه صفتونه A او B لري. (ABC) د ABC ټولګي تکرار دی، او داسې نور.')
b.h('8.1.2 Classification of attributes', '8.1.2 صفات کی درجہ بندی', '8.1.2 د صفتونو ډلبندي')
b.h('Dichotomy or one-way classification', 'دو حصوں میں تقسیم یا یک طرفہ درجہ بندی', 'دوه‌ګونې وېش یا یو اړخیزه ډلبندي')
b.p('When a single attribute is under study, then simple process of classifying the whole data in two groups is called dichotomy which means classifying into two.', 'جب ایک ہی صفت زیرِ مطالعہ ہو تو پورے مواد کو دو گروہوں میں درجہ بند کرنے کا سادہ عمل دو حصوں میں تقسیم (dichotomy) کہلاتا ہے جس کا مطلب ہے دو میں درجہ بندی۔', 'کله چې یو صفت تر څېړنې لاندې وي، نو ټول معلومات په دوو ډلو کې د ډلبندۍ ساده بهیر دوه‌ګونې وېش (dichotomy) بلل کېږي چې مانا یې په دوو وېشل دي.')
b.visual('stat12-attr-dichotomy', attr_tree([['n'], ['(A)', '(α)']], 'Dichotomy: n divided into (A) and (α)', w=260), ratio=.35)
b.p('Since only one attribute is involved, so the division of data is called one-way classification.', 'چونکہ صرف ایک صفت شامل ہے، لہٰذا مواد کی تقسیم یک طرفہ درجہ بندی کہلاتی ہے۔', 'څرنګه چې یوازې یو صفت شامل دی، نو د معلوماتو وېش یو اړخیزه ډلبندي بلل کېږي.')
b.h('Two-way classification', 'دو طرفہ درجہ بندی', 'دوه اړخیزه ډلبندي')
b.p('When two attributes A and B are under study then whole data are classified into four classes or groups as follows:', 'جب دو صفات A اور B زیرِ مطالعہ ہوں تو پورا مواد درج ذیل طرح چار جماعتوں یا گروہوں میں درجہ بند کیا جاتا ہے:', 'کله چې دوه صفتونه A او B تر څېړنې لاندې وي، نو ټول معلومات په لاندې ډول په څلورو ټولګیو یا ډلو ډلبندي کېږي:')
b.visual('stat12-attr-twoway', attr_tree([['n'], ['(A)', '(α)'], ['(B)', '(β)', '(B)', '(β)'], ['(AB)', '(Aβ)', '(αB)', '(αβ)']], 'Two-way classification tree: n → (A),(α) → (B),(β) → (AB),(Aβ),(αB),(αβ)', w=320), ratio=.4)
rec = b.build('stat12-p138-attributes-intro', '8.1 Introduction, notation and classification of attributes', '8.1 صفات کا تعارف، علامات اور درجہ بندی', '8.1 د صفتونو پېژندنه، نښې او ډلبندي', 138, [267, 268])
issues = [{'id': 'stat12-p267-an-female', 'unit': 8, 'printedPage': 267, 'description': 'Class (iv) prints “Non-Muslim an female” (for “and female”); printed wording retained.'}]

